    [
        new MyToken("client.name",  "Client name",  "Full legal name",  "Client"),
        new MyToken("today",        "Today",         "Current date",    "System"),
    ];

    public bool SupportsCreation => false;

    public Task<IEnumerable<IToken>> SearchTokensAsync(string query, CancellationToken ct = default)
    {
        IEnumerable<IToken> r = _tokens;
        if (!string.IsNullOrWhiteSpace(query))
            r = r.Where(t => t.DisplayName.Contains(query, StringComparison.OrdinalIgnoreCase));
        return Task.FromResult(r);
    }

    public void Refresh() { }
}

