private async Task HandleItemsDrop(TreeDropEventArgs<string> args)
{
    // args.TargetNode — the node the items were dropped onto
    // args.DraggedIds — IDs selected in TmMultiViewList
    await MoveItemsAsync(args.DraggedIds, args.TargetNode.Id);
}

private async Task HandleNodeMove(TreeNodeMoveEventArgs<string> args)
{
    // Reparent under new parent, or promote to root if NewParent is null
    await _store.MoveSuiteAsync(args.MovedNode.Id, args.NewParent?.Id);

    // Reload the tree so the new structure is reflected
    _rootNodes = await _store.GetRootNodesAsync();
}

